<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">phase_function = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HenyeyGreensteinPhaseFunction(g=0.7)&quot;</span></span>
